.forge-sl6 .sl6-scrim {position:absolute;inset:0;background:linear-gradient(135deg,rgba(0,0,0,.60) 0%,rgba(0,0,0,0) 55%);z-index:1;pointer-events:none;}

.forge-sl6 .sl6-content {position:absolute;inset:0;z-index:2;}

.forge-sl6 .sl6-content-c {max-width:1440px;margin:0 auto;height:100%;display:flex;flex-direction:column;justify-content:space-between;padding:160px 64px 80px;}

.forge-sl6 .sl6-copy {display:flex;flex-direction:column;gap:32px;max-width:667px;}

.forge-sl6 .sl6-copy-head {display:flex;flex-direction:column;gap:16px;}

.forge-sl6 .sl6-app-lbl {margin:0;font-weight:700;font-size:16px;line-height:20px;color:#fff;}

.forge-sl6 .sl6-hg {display:flex;flex-direction:column;gap:8px;}

.forge-sl6 .sl6-h2 {margin:0;font-family:'Adobe Clean Display','Adobe Clean',sans-serif;font-weight:900;font-size:80px;line-height:76px;letter-spacing:-3.2px;color:#fff;}

.forge-sl6 .sl6-sub {margin:0;font-size:20px;line-height:24px;color:#fff;max-width:500px;}

.forge-sl6 .sl6-cta {display:inline-flex;align-items:center;justify-content:center;background:#fff;color:#000;border:none;border-radius:75px;padding:0 24px;height:40px;font-family:inherit;font-weight:700;font-size:14px;cursor:pointer;}

.forge-sl6 .sl6-router {display:flex;flex-direction:row;justify-content:space-between;align-items:flex-end;gap:24px;}

.forge-sl6 .sl6-tabs {display:flex;flex-direction:row;align-items:flex-end;gap:8px;}

.forge-sl6 .sl6-tab {position:relative;border-radius:8px;padding:12px 12px 16px;width:220px;flex-shrink:0;overflow:hidden;display:flex;flex-direction:column;gap:12px;}

.forge-sl6 .sl6-tab-on {background:#fff;border:1px solid rgba(255,255,255,.10);}

.forge-sl6 .sl6-tab-off {background:rgba(0,0,0,.44);border:1px solid rgba(255,255,255,.11);}

.forge-sl6 .sl6-abar {position:absolute;top:0;left:12px;width:96px;height:4px;background:#eb1000;border-radius:0 0 4px 4px;}

.forge-sl6 .sl6-icons {display:flex;align-items:center;gap:3px;min-height:20px;}

.forge-sl6 .sl6-chip {width:19px;height:18px;border-radius:3px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:7px;font-weight:700;color:#fff;letter-spacing:0;}

.forge-sl6 .sl6-tab-foot {display:flex;align-items:center;justify-content:space-between;gap:8px;}

.forge-sl6 .sl6-lbl-dk {font-weight:700;font-size:14px;line-height:18px;color:#000;}

.forge-sl6 .sl6-lbl-lt {font-weight:700;font-size:14px;line-height:18px;color:#fff;}

.forge-sl6 .sl6-pp {width:40px;height:40px;border-radius:100px;background:rgba(0,0,0,.44);border:1px solid rgba(255,255,255,.11);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;}

.forge-sl6 .sl6-mc {display:none;background:#fff;padding:40px 32px;text-align:center;flex-direction:column;align-items:center;gap:8px;}

.forge-sl6 .sl6-mc-ey {margin:0;font-weight:700;font-size:16px;line-height:20px;color:rgba(0,0,0,.50);}

.forge-sl6 .sl6-mc-h {margin:0;font-family:'Adobe Clean Display',inherit;font-weight:900;font-size:32px;line-height:32px;letter-spacing:-.96px;color:#000;}

.forge-sl6 .sl6-mc-p {margin:0;font-size:16px;line-height:21px;letter-spacing:.16px;color:#101017;}
